package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamHumanBioBank1 {
  private const val T = "මානව දේහ ක්‍රියාවලි හා සෞඛ්‍යය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "මානව ජීව විද්‍යාවට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("මිනිසාගේ මුඛ කුහරයේදී පිෂ්ඨය මෝල්ටෝස් බවට පත් කරන ඛේට එන්සයිමය කුමක්ද?", "ටයලින් (ඛේට ඇමයිලේස්)", "පෙප්සින්", "ලයිපේස්", "ට්‍රිප්සින්", "ඛේටයේ ඇති ටයලින් එන්සයිමය මඟින් රසායනික ජීර්ණය මුඛයේදීම ආරම්භ කෙරේ."),
    q("ආමාශයික යුෂයේ අඩංගු වන හයිඩ්‍රොක්ලෝරික් අම්ලයේ (HCl) ප්‍රධාන කාර්යයක් වන්නේ කුමක්ද?", "ආහාර සමඟ එන බැක්ටීරියා විනාශ කිරීම හා පෙප්සින් සක්‍රිය කිරීම", "පිෂ්ඨය ජීර්ණය කිරීම", "මේදය ඉමල්සිකරණය කිරීම", "ඛනිජ ලවණ සංස්ලේෂණය කිරීම", "HCl ආමාශය තුළ ආම්ලික මාධ්‍යයක් (pH 1.5–2) සපයයි."),
    q("ප්‍රෝටීන පොලිපෙප්ටයිඩ බවට බිඳ දමන ආමාශයේ ඇති ප්‍රධාන ජීර්ණ එන්සයිමය කුමක්ද?", "පෙප්සින්", "ලයිපේස්", "ඇමයිලේස්", "සුක්‍රේස්", "අක්‍රිය පෙප්සිනොජන් HCl මගින් සක්‍රිය පෙප්සින් බවට හැරේ."),
    q("අක්මාව මඟින් නිපදවා පිත්තාශයේ ගබඩා කරන පිත (Bile) ප්‍රධාන වශයෙන් වැදගත් වන්නේ කුමක් සඳහාද?", "මේදය කුඩා බිඳිතිවලට කැඩීම (ඉමල්සිකරණය)", "ප්‍රෝටීන ජීර්ණය කිරීම", "සෙලියුලෝස් බිඳීම", "විටමින් සංස්ලේෂණය", "පිතේ එන්සයිම නොමැති අතර එය මේද ජීර්ණය පහසු කරයි."),
    q("ආහාර ජීර්ණයේ අවසාන ඵල ප්‍රධාන වශයෙන් රුධිරයට අවශෝෂණය වන්නේ කුමන කොටසේදීද?", "ක්ෂුද්‍රාන්ත්‍රයේදී", "ආමාශයේදී", "මහාන්ත්‍රයේදී", "අන්නස්‍රෝතයේදී", "ක්ෂුද්‍රාන්ත්‍ර බිත්තියේ ඇති අංගුලිකා අවශෝෂණ වර්ගඵලය වැඩි කරයි."),
    q("මේද ජීර්ණයෙන් සෑදෙන මේද අම්ල හා ග්ලිසරෝල් අංගුලිකාවල කුමන ව්‍යුහය තුළට අවශෝෂණය වේද?", "පයස්විනී නාලය (Lacteal)", "රුධිර කේශනාලිකා", "මහාන්ත්‍රය", "ග්‍රසනිකාව", "පයස්විනී නාලය වසා පද්ධතියට සම්බන්ධ වේ."),
    q("මහාන්ත්‍රයේ ප්‍රධාන කෘත්‍යය වන්නේ කුමක්ද?", "ජීර්ණය නොවූ කොටස්වලින් ජලය හා ඛනිජ ලවණ අවශෝෂණය කිරීම", "ප්‍රෝටීන ජීර්ණය කිරීම", "ග්ලයිකෝජන් ගබඩා කිරීම", "ඉන්සියුලින් ශ්‍රාවය කිරීම", "මහාන්ත්‍රයේදී අපද්‍රව්‍ය මල බවට ඝන වේ."),
    q("අන්නස්‍රෝතය ඔස්සේ ආහාර ගුලිය ආමාශය කරා තල්ලු වී යන රිද්මයානුකූල පේශි සංකෝචන ක්‍රියාවලිය කුමක්ද?", "ක්‍රමාකුංචනය (Peristalsis)", "ඉමල්සිකරණය", "උත්ස්වේදනය", "ආස්‍රැතිය", "ක්‍රමාකුංචනය ආහාර මාර්ගයේ අනිච්ඡානුග පේශි මඟින් සිදුවේ."),
    q("ආහාර ගිලීමේදී ආහාර කැබලි ශ්වාසනාලය තුළට ඇතුළු වීම වළක්වන කාටිලේජමය වැස්ම කුමක්ද?", "අපිජිහ්විකාව (Epiglottis)", "ස්වරාලය", "ග්‍රසනිකාව", "උපජිහ්විකාව", "ගිලින විට අපිජිහ්විකාව ස්වරාල විවරය වසා දමයි."),
    q("කුඩා දරුවන්ගේ කිරි ප්‍රෝටීන (කේසීන්) කැටි ගැස්වීමට දායක වන ආමාශයික එන්සයිමය කුමක්ද?", "රෙනින්", "ට්‍රිප්සින්", "ඇමයිලේස්", "ලැක්ටේස්", "රෙනින් කිරි ආමාශය තුළ රඳවා ගැනීමට උපකාරී වේ."),
    q("මිනිසාගේ ජීර්ණ එන්සයිම සියල්ලම අන්තර්ගත වන ජීර්ණ යුෂය (ඇමයිලේස්, ට්‍රිප්සින්, ලයිපේස්) කුමක්ද?", "අග්න්‍යාසයික යුෂය", "ඛේටය", "ආමාශයික යුෂය", "පිත", "අග්න්‍යාසයික යුෂය ක්ෂුද්‍රාන්ත්‍රයේ ග්‍රහණිය වෙත මුදා හරී."),
    q("මිනිස් ආමාශයේ අභ්‍යන්තර බිත්තිය හයිඩ්‍රොක්ලෝරික් අම්ලයෙන් හා පෙප්සින් මගින් ජීර්ණය වීමෙන් ආරක්ෂා වන්නේ කෙසේද?", "ශ්ලේෂ්මල ස්තරයක් මගින් ආවරණය වී තිබීමෙන්", "සෙලියුලෝස් බිත්තියකින්", "කැල්සියම් තට්ටුවකින්", "හෘත් පේශිවලින්", "ශ්ලේෂ්මල ස්තරයට හානි වූ විට ගැස්ට්‍රයිටිස් තුවාල ඇති විය හැක."),
    q("සෛලීය ශ්වසනයේදී ඔක්සිජන් භාවිතයෙන් ග්ලූකෝස් සම්පූර්ණයෙන් බිඳ වැටී ලැබෙන අවසාන ඵල මොනවාද?", "කාබන් ඩයොක්සයිඩ්, ජලය සහ ශක්තිය", "ලැක්ටික් අම්ලය සහ ශක්තිය", "එතනෝල් සහ CO₂", "ඔක්සිජන් සහ ග්ලූකෝස්", "C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + ATP ශක්තිය."),
    q("වේගයෙන් දිවීමේදී පේශිවලට ප්‍රමාණවත් ඔක්සිජන් නොලැබීම නිසා සිදුවන නිර්වායු ශ්වසනයේදී නිපදවෙන අම්ලය කුමක්ද?", "ලැක්ටික් අම්ලය", "හයිඩ්‍රොක්ලෝරික් අම්ලය", "ඇසිටික් අම්ලය", "සල්ෆියුරික් අම්ලය", "ලැක්ටික් අම්ලය එකතු වීමෙන් පේශි වෙහෙස හා කැක්කුම ඇතිවේ."),
    q("මානව පෙනහැලි තුළ වායු හුවමාරුව සිදුවන කුඩා වායු කෝෂ මොනවාද?", "ගර්ත (Alveoli)", "ශ්වාසනාලිකා", "ශ්වාසනාලය", "ප්ලූරාව", "ගර්ත බිත්ති තනි සෛල ඝනකමකින් යුක්ත වන අතර තෙත්ව පවතී."),
    q("පෙනහැලි තුළ ගර්තවලින් රුධිරයට ඔක්සිජන් ඇතුළු වන භෞතික ක්‍රියාවලිය කුමක්ද?", "විසරණය", "ආස්‍රැතිය", "සක්‍රිය පරිවහනය", "වාෂ්පීකරණය", "වැඩි ආංශික පීඩනයේ සිට අඩු ආංශික පීඩනයට වායු විසරණය වේ."),
    q("මානව ආශ්වාස ක්‍රියාවලියේදී ප්‍රාචීරය හා අන්තර් පර්ශුක පේශිවලට කුමක් සිදුවේද?", "සංකෝචනය වී ප්‍රාචීරය පැතැලි වී උරස් කුහරයේ පරිමාව වැඩි වේ", "ඉහිල් වී පෙනහැලි හැකිලේ", "උරස් පරිමාව අඩු වේ", "ප්‍රාචීරය ඉහළට නැමේ", "උරස් කුහරයේ පීඩනය අඩු වීමෙන් බාහිර වාතය පෙනහැලි තුළට ඇදේ."),
    q("ශ්වාසනාලය හා ශ්වාසනාලිකා හැකිලී වසා යාම වැළැක්වීම සඳහා පිහිටි C-හැඩැති ආධාරක ව්‍යුහ මොනවාද?", "කාටිලේජ මුදු", "අස්ථි මුදු", "සිනිඳු පේශි මුදු", "කණ්ඩරා", "කාටිලේජ මුදු නිරන්තර වායු ගමනාගමනය තහවුරු කරයි."),
    q("මානව රුධිරයේ ද්‍රව මාධ්‍යය වන රුධිර ප්ලාස්මාවේ වැඩිපුරම අඩංගු වන්නේ කුමක්ද?", "ජලය (90% පමණ)", "රතු රුධිරාණු", "මේද අම්ල", "සෙලියුලෝස්", "ප්ලාස්මාව තුළ ප්ලාස්මා ප්‍රෝටීන, හෝමෝන, ග්ලූකෝස් හා යූරියා දියවී ඇත."),
    q("දේහය තුළ ඔක්සිජන් පරිවහනය කිරීම සඳහා හිමොග්ලොබින් වර්ණකය අඩංගු රුධිර සෛලය කුමක්ද?", "රතු රුධිරාණු", "සුදු රුධිරාණු", "පට්ටිකා", "වසා සෛල", "ද්වි-අවතල මඩලක හැඩය නිසා වායු හුවමාරුවට වැඩි පෘෂ්ඨයක් ලැබේ."),
    q("තුවාලයකින් ලේ ගැලීම නැවැත්වීමට රුධිරය කැටි ගැසීමේදී මූලිකව ක්‍රියා කරන රුධිර සංඝටකය කුමක්ද?", "රුධිර පට්ටිකා", "රතු රුධිරාණු", "නියුට්‍රොෆිල", "ලිම්ෆොසයිට", "පට්ටිකා මඟින් ත්‍රොම්බොප්ලාස්ටින් නිදහස් කර ෆයිබ්‍රින් දැල සෑදීම ආරම්භ කරයි."),
    q("දේහයට ඇතුළු වන රෝග කාරක විෂබීජ ගිල දමා විනාශ කරන හෝ ප්‍රතිදේහ නිපදවන රුධිර සෛල මොනවාද?", "සුදු රුධිරාණු", "රතු රුධිරාණු", "පට්ටිකා", "අස්ථි සෛල", "භක්ෂ සෛල බැක්ටීරියා භක්ෂණය කරන අතර ලිම්ෆොසයිට ප්‍රතිදේහ සාදයි."),
    q("පෙනහැලිවල සිට ඔක්සිජනීකෘත රුධිරය හෘදයේ වම් කර්ණිකාවට රැගෙන එන රුධිර වාහිනිය කුමක්ද?", "පුප්ඵුශීය ශිරාව", "පුප්ඵුශීය ධමනිය", "මහා ධමනිය", "උත්තර මහා ශිරාව", "සාමාන්‍යයෙන් ධමනි ඔක්සිජනීකෘත රුධිරය ගෙන ගියද පුප්ඵුශීය ධමනිය හා ශිරාව ඊට ප්‍රතිවිරුද්ධය."),
    q("දේහයේ සියලුම කොටස් වෙත ඔක්සිජනීකෘත රුධිරය පොම්ප කරන හෘදයේ ඝනම මාංසල බිත්තියක් ඇති කුටීරය කුමක්ද?", "වම් කෝෂිකාව", "දකුණු කෝෂිකාව", "වම් කර්ණිකාව", "දකුණු කර්ණිකාව", "දේහය පුරා ඉහළ පීඩනයකින් රුධිරය යැවීමට වම් කෝෂිකාව ඝන බිත්තියකින් යුක්තය."),
    q("හෘදයේ කෝෂිකා සංකෝචනය වන විට රුධිරය ආපසු කර්ණිකා වෙත ගලා යාම වළක්වන කපාට මොනවාද?", "ද්විතුණ්ඩ හා ත්‍රිතුණ්ඩ කපාට", "අඩසඳ කපාට", "ශිරා කපාට", "පුප්ඵුශීය කපාට", "දකුණේ ත්‍රිතුණ්ඩ කපාටය ද වමේ ද්විතුණ්ඩ (මිට්‍රල්) කපාටය ද පිහිටයි."),
    q("රුධිරය පහළ සිට ඉහළට නැවත ගලා යාම වැළැක්වීම සඳහා අභ්‍යන්තරයේ කපාට පිහිටා ඇති රුධිර නාල වර්ගය කුමක්ද?", "ශිරා", "ධමනි", "කේශනාලිකා", "මහා ධමනිය", "ශිරාවල රුධිර පීඩනය අඩු බැවින් පසුපසට ගැලීම වැළැක්වීමට කපාට ඇත."),
    q("රුධිර ප්ලාස්මාවේ ඇති කුමන ප්‍රෝටීනය දේහ ආසාදනවලට එරෙහිව ප්‍රතිදේහ ලෙස ක්‍රියා කරයිද?", "ග්ලොබියුලින්", "ෆයිබ්‍රිනොජන්", "කෙරටින්", "මයෝසින්", "ප්‍රතිශක්ති ග්ලොබියුලින් රෝග කාරක උදාසීන කරයි."),
    q("රුධිර කාණ්ඩ අනුව හදිසි අවස්ථාවකදී O⁻ (O රින) රුධිරය 'සර්ව දායකයා' ලෙස හඳුන්වන්නේ ඇයි?", "රතු රුධිරාණු මතුපිට A, B හා Rh ප්‍රතිදේහජනක නොමැති නිසා", "සියලු ප්‍රතිදේහජනක ඇති නිසා", "ප්ලාස්මාවේ ප්‍රතිදේහ නොමැති නිසා", "හිමොග්ලොබින් වැඩි නිසා", "ප්‍රතිදේහජනක නොමැති නිසා ප්‍රතිග්‍රාහකයාගේ රුධිරයේ කැටි ගැසීමක් ඇති නොවේ."),
    q("AB⁺ රුධිර කාණ්ඩය හිමි පුද්ගලයෙකු 'සර්ව ප්‍රතිග්‍රාහකයා' ලෙස හැඳින්වීමට හේතුව කුමක්ද?", "ප්ලාස්මාවේ ප්‍රති-A හෝ ප්‍රති-B ප්‍රතිදේහ නොමැති වීම", "රතු රුධිරාණු නොමැති වීම", "O ප්‍රතිදේහ තිබීම", "පට්ටිකා වැඩි වීම", "ප්‍රතිදේහ නොමැති නිසා ඕනෑම කාණ්ඩයක රුධිරය පාරවිලයනය කළ හැක."),
    q("මානව සාමාන්‍ය හෘද ස්පන්දනය ආරම්භ කර පාලනය කරන දකුණු කර්ණිකාවේ පිහිටි ව්‍යුහය කුමක්ද?", "සයිනස්-කර්ණිකා ගැටය (SA node / ස්වාභාවික පේස්මේකරය)", "කර්ණික-කෝෂික ගැටය", "පර්කින්ජේ තන්තු", "මහා ධමනි ආරුක්කුව", "SA ගැටය හෘදයේ රිද්මයානුකූල ස්පන්දනය ජනනය කරයි."),
    q("මිනිසාගේ රුධිර සංසරණයේදී හෘදය හරහා රුධිරය දෙවරක් ගමන් කිරීම හඳුන්වන්නේ කුමන නමින්ද?", "ද්විත්ව සංසරණය", "ඒක සංසරණය", "විවෘත සංසරණය", "වසා සංසරණය", "පුප්ඵුශීය සංසරණය හා සංස්ථානික සංසරණය ලෙස කොටස් දෙකකි."),
    q("නිරෝගී වැඩිහිටි මිනිසෙකුගේ සාමාන්‍ය විවේක රුධිර පීඩනය කොපමණද?", "120/80 mmHg", "80/120 mmHg", "160/100 mmHg", "90/50 mmHg", "ආකුංච පීඩනය 120 mmHg ද විස්තාර පීඩනය 80 mmHg ද වේ."),
    q("මානව වකුගඩුවේ ව්‍යුහමය හා කෘත්‍යමය මූලික ඒකකය කුමක්ද?", "නෙෆ්‍රෝනය (වෘක්කාණුව)", "නියුරෝනය", "ගර්තය", "අංගුලිකාව", "එක් වකුගඩුවක නෙෆ්‍රෝන මිලියනයක් පමණ පිහිටා ඇත."),
    q("නෙෆ්‍රෝනයේ ග්ලෝමෙරුලසයේ සිට බෝමන් ප්‍රාවරය තුළට ද්‍රව්‍ය පෙරී යන පළමු ක්‍රියාවලිය කුමක්ද?", "අතිපෙරීම (Ultrafiltration)", "වරණීය ප්‍රතිශෝෂණය", "ස්‍රාවය", "ආස්‍රැතිය", "රුධිර ප්‍රෝටීන හා රුධිර සෛල ප්‍රමාණයෙන් විශාල බැවින් නොපෙරේ."),
    q("නිරෝගී පුද්ගලයෙකුගේ ග්ලෝමෙරුලස් පෙරනයේ ඇති නමුත් සම්පූර්ණයෙන්ම රුධිරයට ප්‍රතිශෝෂණය කර ගන්නා සංඝටකය කුමක්ද?", "ග්ලූකෝස්", "යූරියා", "යූරික් අම්ලය", "ක්‍රියැටිනින්", "නිරෝගී අයෙකුගේ මුත්‍රවල ග්ලූකෝස් නොමැති අතර දියවැඩියාවේදී පිටවිය හැක."),
    q("මානව දේහයේ ප්‍රධාන නයිට්‍රජනීය බහිස්ස්‍රාවී ඵලය වන යූරියා නිපදවනු ලබන්නේ කුමන අවයවයේදීද?", "අක්මාවේදී", "වකුගඩුවලදී", "ආමාශයේදී", "පෙනහැලිවලදී", "අතිරික්ත ඇමයිනෝ අම්ල අක්මාවේදී විඇමිනීකරණය වී යූරියා සෑදේ."),
    q("මානව වකුගඩු මඟින් දේහයේ ජල සමතුලිතතාව පාලනය කිරීමේදී මුත්‍ර මඟින් ජලය අඩුවෙන් පිට කිරීමට බලපාන හෝමෝනය කුමක්ද?", "ADH (ප්‍රතිමූත්‍රක හෝමෝනය)", "ඉන්සියුලින්", "ඇඩ්‍රිනලින්", "තයිරොක්සින්", "පිටියුටරි ග්‍රන්ථියෙන් ශ්‍රාවය වන ADH වෘක්ක නාලිකාවල ජල ප්‍රතිශෝෂණය වැඩි කරයි."),
    q("සමෙහි පිහිටි ස්වේද ග්‍රන්ථි මඟින් පිට කරන දහඩිය මගින් සිදුවන ප්‍රධාන කාර්යයන් දෙක මොනවාද?", "දේහ උෂ්ණත්වය පාලනය හා සුළු බහිස්ස්‍රාවය", "ආහාර ජීර්ණය හා ශ්වසනය", "හෝමෝන නිපදවීම හා රුධිරය පෙරීම", "ප්‍රෝටීන සංස්ලේෂණය", "දහඩිය වාෂ්ප වීමෙන් දේහය සිසිල් වේ."),
    q("මානව මධ්‍ය ස්නායු පද්ධතිය සමන්විත වන්නේ කුමන කොටස් දෙකෙන්ද?", "මොළය සහ සුෂුම්නාව", "හෘදය සහ පෙනහැලි", "කපාල ස්නායු හා සුෂුම්නා ස්නායු", "ඇස සහ කණ", "සියලු ස්නායු ක්‍රියාකාරකම් සම්බන්ධීකරණය කරන ප්‍රධාන මධ්‍යස්ථානයයි."),
    q("සමබරතාව, ඉරියව් පවත්වා ගැනීම සහ පේශි චලන සම්බන්ධීකරණය පාලනය කරන මොළයේ කොටස කුමක්ද?", "අනුමස්තිෂ්කය (Cerebellum)", "මස්තිෂ්කය (Cerebrum)", "සුෂුම්නා ශීර්ෂකය", "හයිපොතැලමසය", "මත්පැන් පානය කළ විට අනුමස්තිෂ්කයේ ක්‍රියාව අඩාල වී සමබරතාව නැති වේ."),
    q("හෘද ස්පන්දනය, ශ්වසනය හා රුධිර පීඩනය වැනි අනිච්ඡානුග ක්‍රියා පාලනය කරන මොළයේ කොටස කුමක්ද?", "සුෂුම්නා ශීර්ෂකය (Medulla oblongata)", "අනුමස්තිෂ්කය", "මස්තිෂ්ක බාහිකය", "පිටියුටරි ග්‍රන්ථිය", "සුෂුම්නා ශීර්ෂකයට හානි වුවහොත් ජීවිතයට දැඩි අනතුරක් සිදුවේ."),
    q("බුද්ධිය, මතකය, සිතීම හා ඉච්ඡානුග චලන පාලනය කරන මොළයේ විශාලතම කොටස කුමක්ද?", "මස්තිෂ්කය", "අනුමස්තිෂ්කය", "සුෂුම්නා ශීර්ෂකය", "තැලමසය", "මස්තිෂ්කය අර්ධගෝල දෙකකින් සමන්විත වේ."),
    q("උණුසුම් භාජනයක් ඇල්ලූ විගස අත ඉවතට ගැනීමේ සුෂුම්නා ප්‍රතීක ක්‍රියාවේ නියුරෝන ගමන් පථය කුමක්ද?", "ප්‍රතිග්‍රාහකය → සංවේදී නියුරෝනය → අන්තර්හාර නියුරෝනය → චාලක නියුරෝනය → කාරකය", "චාලක → සංවේදී → මොළය → කාරකය", "මොළය → ප්‍රතිග්‍රාහකය → චාලක → අන්තර්හාර", "කාරකය → චාලක → සංවේදී → ප්‍රතිග්‍රාහකය", "ප්‍රතීක ක්‍රියා මොළයේ සිතීමකින් තොරව ඉතා වේගයෙන් ආරක්ෂාව සපයයි."),
    q("ස්නායු ආවේගයක් එක් නියුරෝනයක සිට ඊළඟ නියුරෝනයට සම්ප්‍රේෂණය වන සියුම් හිදැස කුමක්ද?", "උපාගමය (Synapse)", "ඇක්සනය", "ඩෙන්ඩ්‍රයිටය", "මයලින් කොපුව", "උපාගමය හරහා ස්නායු සම්ප්‍රේෂක රසායනික ද්‍රව්‍ය මඟින් සංඥාව ගමන් කරයි."),
    q("මිනිස් ඇසේ ආලෝක සංවේදී කේතු හා යෂ්ටි සෛල පිහිටා ඇති අභ්‍යන්තරම ස්තරය කුමක්ද?", "දෘෂ්ටි විතානය (Retina)", "ශ්වේත පටලය", "රුධිරග්‍රාහී පටලය", "තාරා මණ්ඩලය", "දෘෂ්ටි විතානය මත තාත්වික යටිකුරු ප්‍රතිබිම්බයක් සෑදේ."),
    q("දීප්තිමත් ආලෝකයකදී හා අඳුරේදී ඇසට ඇතුළු වන ආලෝක ප්‍රමාණය කණිනිකාවේ ප්‍රමාණය වෙනස් කරමින් පාලනය කරන කොටස කුමක්ද?", "තාරා මණ්ඩලය (Iris)", "ස්වච්ඡ මණ්ඩලය", "අක්ෂි කාචය", "ප්‍රතීත දේහය", "ඇසේ වර්ණය තීරණය වන්නේ ද තාරා මණ්ඩලයේ වර්ණක අනුවය."),
    q("වස්තුවක් ඇසට ළං වන විට හා ඈත් වන විට අක්ෂි කාචයේ වක්‍රතාව වෙනස් කර නාභිගත කිරීමට (සමායෝජනය) දායක වන ව්‍යුහය කුමක්ද?", "ප්‍රතීත පේශි හා අවලම්බන බන්ධනී", "තාරා මණ්ඩලය", "දෘෂ්ටි විතානය", "කචාභ රසය", "ළඟ බැලීමේදී ප්‍රතීත පේශි සංකෝචනය වී කාචය උත්තල වේ."),
    q("රාත්‍රියේ හා අඩු ආලෝකයේදී කළු-සුදු පෙනීම ලබාදෙන දෘෂ්ටි විතානයේ සෛල වර්ගය කුමක්ද?", "යෂ්ටි සෛල (Rods)", "කේතු සෛල (Cones)", "කහ ලපය", "අන්ධ බින්දුව", "කේතු සෛල වර්ණ හඳුනා ගැනීමට දීප්තිමත් ආලෝකයේදී ක්‍රියා කරයි."),
    q("මානව කණේ ශබ්ද තරංග කම්පන අභ්‍යන්තර කණේ කර්ණ ශංඛය වෙත සම්ප්‍රේෂණය කරන කුඩා අස්ථි තුන මොනවාද?", "මුද්ගරය, නිඝාතය හා ධරණකය", "කළවා අස්ථිය, ජංඝාස්ථිය, පාද අස්ථි", "කශේරුකා, උරෝස්ථිය, පර්ශු", "හනු අස්ථි, නාසා අස්ථි, කපාලය", "මැද කණේ ඇති මෙම අස්ථි තුන ශබ්ද කම්පන වර්ධනය කරයි."),
    q("මානව දේහයේ සමබරතාව පවත්වා ගැනීමට දායක වන අභ්‍යන්තර කණේ පිහිටි ව්‍යුහය කුමක්ද?", "අර්ධ වෘත්තාකාර නාල", "කර්ණ ශංඛය", "කර්ණ පටහ පටලය", "යුස්ටේකීය නාලය", "අර්ධ වෘත්තාකාර නාල තුන එකිනෙකට ලම්භකව පිහිටා ශීර්ෂයේ චලන හඳුනා ගනී."),
    q("රුධිරයේ ග්ලූකෝස් මට්ටම අධික වූ විට එය ග්ලයිකෝජන් බවට හරවා මට්ටම අඩු කරන හෝමෝනය කුමක්ද?", "ඉන්සියුලින්", "ග්ලූකොගොන්", "ඇඩ්‍රිනලින්", "තයිරොක්සින්", "අග්න්‍යාසයේ ලැන්ගහැන් දීපිකා මඟින් ඉන්සියුලින් ශ්‍රාවය කෙරේ."),
    q("හදිසි බියවීමකදී හෝ කෝපවීමකදී හෘද ස්පන්දනය හා රුධිර පීඩනය වැඩි කරන 'සටනට හෝ පලා යාමට' සූදානම් කරන හෝමෝනය කුමක්ද?", "ඇඩ්‍රිනලින්", "ඉන්සියුලින්", "ADH", "ප්‍රොජෙස්ටරෝන්", "වකුගඩු මත පිහිටි අධිවෘක්ක ග්‍රන්ථි මඟින් ඇඩ්‍රිනලින් ශ්‍රාවය වේ."),
    q("පුරුෂ ප්‍රජනක පද්ධතියේ ශුක්‍රාණු නිපදවන අතරම ටෙස්ටොස්ටෙරෝන් හෝමෝනය නිපදවන ඉන්ද්‍රිය කුමක්ද?", "වෘෂණ", "පුරස්ථි ග්‍රන්ථිය", "ශුක්‍ර ආශයිකාව", "අපිවෘෂණය", "ශුක්‍රාණු නිපදවීමට දේහ උෂ්ණත්වයට වඩා අඩු උෂ්ණත්වයක් අවශ්‍ය බැවින් වෘෂණ කෝෂයේ පිහිටයි."),
    q("ස්ත්‍රී ප්‍රජනක පද්ධතියේ ඩිම්බයක් ශුක්‍රාණුවක් සමඟ සංසේචනය සිදුවන ස්ථානය කුමක්ද?", "පැලෝපීය නාලය", "ගර්භාෂය", "ඩිම්බකෝෂය", "යෝනි මාර්ගය", "සංසේචිත යුක්තාණුව පසුව ගර්භාෂ බිත්තියේ අධිරෝපණය වේ."),
    q("මාසික ආර්තව චක්‍රයේ 14 වන දිනය ආසන්නයේදී පරිණත ඩිම්බකෝෂ ස්‍රාවයෙන් ඩිම්බයක් මුදා හැරීම හඳුන්වන්නේ කුමන නමින්ද?", "ඩිම්බ මෝචනය (Ovulation)", "ආර්තවය", "සංසේචනය", "අධිරෝපණය", "ඩිම්බ මෝචනය LH හෝමෝන මට්ටම ඉහළ යාමෙන් සිදුවේ."),
    q("කළලය මවගේ රුධිරයෙන් පෝෂණය හා ඔක්සිජන් ලබා ගන්නා අතර අපද්‍රව්‍ය බැහැර කරන තාවකාලික අවයවය කුමක්ද?", "කළලබන්ධය (Placenta)", "උල්බ කෝෂය", "ඩිම්බ නාලය", "ගැබ්ගෙල", "පෙකණි වැල මඟින් කළලය කළලබන්ධයට සම්බන්ධ වේ."),
    q("බෝ නොවන රෝගයක් වන දෙවන වර්ගයේ දියවැඩියාව වැළැක්වීමට ගත හැකි හොඳම පුරුද්ද කුමක්ද?", "සමබල ආහාර වේලක් සහ නිතිපතා ව්‍යායාම කිරීම", "අධික සීනි හා මේද ආහාර ගැනීම", "ප්‍රතිජීවක ඖෂධ ගැනීම", "ජලය පානය නොකිරීම", "දියවැඩියාව, අධි රුධිර පීඩනය හා හෘද රෝග ජීවන රටාව සමඟ බැඳී පවතී."),
    q("ඩෙංගු රෝගය මිනිසෙකුගෙන් තවත් මිනිසෙකුට සම්ප්‍රේෂණය කරන වාහක මදුරු විශේෂය කුමක්ද?", "ඊඩිස් (Aedes) මදුරුවා", "ඇනොෆිලිස් මදුරුවා", "කියුලෙක්ස් මදුරුවා", "වැලි මැස්සා", "ඊඩිස් මදුරුවන් ප්‍රධාන වශයෙන් දිවා කාලයේදී දෂ්ට කරයි."),
    q("මැලේරියා රෝගය ඇති කරන ප්‍රොටිස්ටා රෝග කාරකයා කවුද?", "ප්ලාස්මෝඩියම් (Plasmodium)", "ඩෙංගු වෛරසය", "ටයිපොයිඩ් බැක්ටීරියාව", "කොලරා විබ්‍රියෝ", "ගැහැණු ඇනොෆිලිස් මදුරුවා මැලේරියා රෝග කාරකයා සම්ප්‍රේෂණය කරයි."),
    q("කොරොනරි ධමනි අවහිර වීම නිසා හෘත් පේශියට රුධිර සැපයුම නතර වී ඇතිවන භයානක තත්ත්වය කුමක්ද?", "හෘදයාබාධය (Myocardial infarction)", "නීරක්තිය", "ගැස්ට්‍රයිටිස්", "ඇදුම", "අධික කොලෙස්ටරෝල් හා දුම්පානය කොරොනරි ධමනි අවහිර වීමට හේතු වේ."),
    q("බිහි වූ අලුත දරුවාට මව්කිරිවලින් මුල් දින කිහිපයේදී ලැබෙන කොලොස්ට්‍රම්වල ඇති ප්‍රධාන වාසිය කුමක්ද?", "රෝගවලට එරෙහි ප්‍රතිදේහ අඩංගු වී ස්වාභාවික ප්‍රතිශක්තිය ලබාදීම", "අධික පිෂ්ඨය සැපයීම", "රතු රුධිරාණු සැපයීම", "අම්ල ගතිය වැඩි කිරීම", "මව්කිරි ළදරුවාට අක්‍රිය ප්‍රතිශක්තිය ලබා දෙයි."),
    q("පියයුරු පිළිකා නොවන පෙනහැලි පිළිකා හා ශ්වසන ආබාධ ඇති වීමට ප්‍රධානතම හේතුව කුමක්ද?", "දුම්පානය කිරීම", "අධිකව ජලය බීම", "පළතුරු අනුභවය", "ව්‍යායාම කිරීම", "දුම්කොළ දුමේ තාර, නිකොටින් සහ කාබන් මොනොක්සයිඩ් අඩංගු වේ."),
    q("දුම්පානයේදී රුධිරයේ හිමොග්ලොබින් සමඟ ස්ථිරව බැඳී ඔක්සිජන් පරිවහන ධාරිතාව අඩු කරන විෂ වායුව කුමක්ද?", "කාබන් මොනොක්සයිඩ් (CO)", "ඔක්සිජන්", "නයිට්‍රජන්", "හීලියම්", "CO හිමොග්ලොබින් සමඟ කාබොක්සිහිමොග්ලොබින් සාදයි."),
    q("මානව අන්තඃශ්‍රාවී පද්ධතියේ 'ප්‍රධාන ග්‍රන්ථිය' ලෙස හඳුන්වන අනෙකුත් ග්‍රන්ථි පාලනය කරන ග්‍රන්ථිය කුමක්ද?", "පිටියුටරි ග්‍රන්ථිය", "තයිරොයිඩ් ග්‍රන්ථිය", "අග්න්‍යාසය", "අධිවෘක්ක ග්‍රන්ථිය", "පිටියුටරි ග්‍රන්ථිය මොළයේ පාදමේ හයිපොතැලමසයට සම්බන්ධව පිහිටයි."),
    q("දේහ උෂ්ණත්වය 37°C පමණ නියතව පවත්වා ගැනීම සඳහා තාප විපර්යාස සංවේදනය කර පාලනය කරන මොළයේ කොටස කුමක්ද?", "හයිපොතැලමසය", "අනුමස්තිෂ්කය", "මස්තිෂ්ක බාහිකය", "සුෂුම්නාව", "හයිපොතැලමසය දේහයේ තාප නියාමක මධ්‍යස්ථානයයි."),
    q("උදරයේ වම් පැත්තේ පිහිටි ආමාශයේ ඉහළ ආහාර පැමිණීමේදී ආහාර ආපසු අන්නස්‍රෝතයට යාම වළක්වන කපාට ව්‍යුහය කුමක්ද?", "හෘද චක්‍ර පේශි මුදුව (Cardiac sphincter)", "ජඨර නිර්ගම මුදුව", "අපිජිහ්විකාව", "ත්‍රිතුණ්ඩ කපාටය", "පෙරිස්ටැල්සිස් ක්‍රියාවෙන් ආහාර ආමාශයට පැමිණේ."),
    q("මානව මුත්‍රවල අඩංගු සාමාන්‍ය කහ පැහැයට හේතු වන වර්ණකය නිපදවෙන්නේ කුමක් බිඳ වැටීමෙන්ද?", "මිය ගිය රතු රුධිරාණුවල හිමොග්ලොබින්", "සුදු රුධිරාණු", "පිෂ්ඨය", "ග්ලයිකෝජන්", "අක්මාවේදී හිමොග්ලොබින් බිඳී පිත් වර්ණක හා යුරෝක්‍රෝම් සෑදේ."),
    q("අස්ථි බන්ධනියක් ඉරී යාම හෝ සන්ධියක් ඇඹරී යාම නිසා ඇතිවන තුවාලය හඳුන්වන්නේ කෙසේද?", "උළුක්කුව (Sprain)", "අස්ථි බිඳුම", "ආතරයිටිස්", "ඔස්ටියෝපොරෝසිස්", "වහාම අයිස් තැබීම හා විවේකය ලබාදීම ප්‍රථමාධාර වේ."),
    q("වයස්ගත වීමත් සමඟ කැල්සියම් ඌනතාව නිසා අස්ථිවල ඝනත්වය අඩු වී පහසුවෙන් බිඳෙන සුළු වීමේ රෝගය කුමක්ද?", "ඔස්ටියෝපොරෝසිස්", "රිකට්ස්", "ස්කර්වි", "ගවුට්", "විටමින් D හා කැල්සියම් ප්‍රමාණවත්ව ගැනීමෙන් මෙය වළක්වා ගත හැක."),
    q("මානව ඇසේ දුර දැකීමේ දෝෂයක් වන අවිදුර දෘෂ්ටිකත්වය (Myopia - ළඟ පෙනීම) නිවැරදි කිරීමට පළඳින කාචය කුමක්ද?", "අවතල කාචයක්", "උත්තල කාචයක්", "සිලින්ඩරාකාර කාචයක්", "තල වීදුරුවක්", "අවිදුර දෘෂ්ටිකත්වයේදී ඈත වස්තු දෘෂ්ටි විතානයට ඉදිරියෙන් නාභිගත වේ."),
    q("ළඟ ඇති පොතක් කියවීමට අපහසු දූර දෘෂ්ටිකත්වය (Hypermetropia - දුර පෙනීම) නිවැරදි කිරීමට යොදන කාචය කුමක්ද?", "උත්තල කාචයක්", "අවතල කාචයක්", "ද්වි-අවතල කාචයක්", "ප්‍රිස්මයක්", "දූර දෘෂ්ටිකත්වයේදී ආලෝක කිරණ දෘෂ්ටි විතානයට පිටුපසින් නාභිගත වේ."),
    q("මධ්‍ය කණ හා උගුර (ග්‍රසනිකාව) එකිනෙක සම්බන්ධ කරමින් කර්ණ පටහ පටලය දෙපස වායු පීඩනය සමතුලිත කරන නාලය කුමක්ද?", "යුස්ටේකීය නාලය", "කර්ණ ශංඛය", "පිටත ශ්‍රවණ නාලය", "අර්ධ වෘත්තාකාර නාලය", "ගුවන් යානයක ඉහළ නගින විට ගිලීම මගින් මෙම නාලය විවෘත වී පීඩනය සමනය වේ."),
    q("සෛලීය ශ්වසනය සඳහා ඔක්සිජන් භාවිත නොකරන රතු රුධිරාණු ඇතුළු සියලු සෛලවල ශක්ති නිෂ්පාදන ක්‍රියාවලියේ ආරම්භක පියවර කුමක්ද?", "ග්ලයිකොලිසිස්", "ක්‍රෙබ්ස් චක්‍රය", "ප්‍රභාසංස්ලේෂණය", "කැල්වින් චක්‍රය", "ග්ලයිකොලිසිසය සෛල ප්ලාස්මයේදී ඔක්සිජන් නොමැතිව සිදුවේ."),
    q("වැඩුණු මිනිසෙකුගේ දත් සැකැස්ම අනුව ආහාර ඉරීමට විශේෂිත වූ උල් දත් වර්ගය කුමක්ද?", "රදනක දත් (Canines)", "කෘන්තක දත්", "පුරශ්චාර්වක දත්", "චාර්වක දත්", "කෘන්තක කැපීමට ද චාර්වක ඇඹරීමට ද භාවිත වේ."),
    q("දත්වල එනැමලය ආරක්ෂා කර ගැනීම සඳහා පානීය ජලයේ හා දන්තාලේපවල සුළු ප්‍රමාණයකින් අඩංගු විය යුතු මූලද්‍රව්‍යය කුමක්ද?", "ෆ්ලෝරීන් (ෆ්ලෝරයිඩ්)", "ක්ලෝරීන්", "සල්ෆර්", "රසදිය", "අධික ෆ්ලෝරයිඩ් ප්‍රමාණය දත්වල කහ පැහැ ෆ්ලෝරෝසිස් ඇති කරයි."),
    q("මානව ශ්වසන පද්ධතියේ ආශ්වාස කරන වාතය තෙත් කිරීම, උණුසුම් කිරීම සහ දූවිලි පෙරීම සිදු වන්නේ කොතැනදීද?", "නාසා කුහරයේදී", "ගර්තවලදී", "ආමාශයේදී", "ගලනාලයේදී", "නාසයේ ඇති රෝම හා ශ්ලේෂ්මල අපද්‍රව්‍ය රඳවා ගනී."),
    q("මානව ප්‍රශ්වාස වාතයේ ආශ්වාස වාතයට වඩා කාබන් ඩයොක්සයිඩ් ප්‍රතිශතය කොපමණ පමණ වේද?", "4% පමණ", "0.04% පමණ", "21% පමණ", "78% පමණ", "ආශ්වාසයේ CO₂ 0.04% ක් වන අතර ප්‍රශ්වාසයේ 4% දක්වා ඉහළ යයි."),
    q("සිරුරේ සීනි මට්ටම අඩු වූ විට අක්මාවේ ඇති ග්ලයිකෝජන් ග්ලූකෝස් බවට පත් කර රුධිරයට එක් කරන හෝමෝනය කුමක්ද?", "ග්ලූකොගොන්", "ඉන්සියුලින්", "ටෙස්ටොස්ටෙරෝන්", "ඊස්ට්‍රජන්", "ඉන්සියුලින් හා ග්ලූකොගොන් ප්‍රතිවිරුද්ධව ක්‍රියා කර රුධිර ග්ලූකෝස් මට්ටම තුලනය කරයි."),
    q("තයිරොයිඩ් ග්‍රන්ථියෙන් නිපදවෙන තයිරොක්සින් හෝමෝනය මඟින් පාලනය කරන ප්‍රධාන ක්‍රියාවලිය කුමක්ද?", "දේහයේ පරිවෘත්තීය සීඝ්‍රතාව පාලනය කිරීම", "රුධිර කැටි ගැසීම", "පෙනහැලි පිරිසිදු කිරීම", "ආහාර ඉමල්සිකරණය", "ළමා වියේ තයිරොක්සින් ඌනතාව ක්‍රෙටිනිස්ම් තත්ත්වය ඇති කරයි."),
    q("ශ්‍රී ලංකාවේ බහුලව වාර්තා වන දිගුකාලීන වකුගඩු රෝගය (CKDu) වැළැක්වීම සඳහා වඩාත්ම නිර්දේශිත පියවර කුමක්ද?", "පිරිසිදු පානීය ජලය භාවිතය හා කෘෂි රසායන අවම කිරීම", "ලුණු අධිකව ආහාරයට ගැනීම", "ජලය පානය නොකිරීම", "ප්‍රෝටීන සම්පූර්ණයෙන් නැවැත්වීම", "වකුගඩු සෞඛ්‍යයට පිරිසිදු ජලය ප්‍රමාණවත්ව පානය කිරීම ඉතා වැදගත් වේ."),
    q("ස්ත්‍රී දේහයේ ද්විතීයික ලිංගික ලක්ෂණ ඇති කිරීමට සහ ගර්භාෂ බිත්තිය සකස් කිරීමට මූලික වන ඩිම්බකෝෂ හෝමෝනය කුමක්ද?", "ඊස්ට්‍රජන්", "ටෙස්ටොස්ටෙරෝන්", "ඇඩ්‍රිනලින්", "ඉන්සියුලින්", "ඩිම්බකෝෂයෙන් ඊස්ට්‍රජන් හා ප්‍රොජෙස්ටරෝන් ශ්‍රාවය වේ."),
    q("මිනිස් දේහයේ පේශියක් අස්ථියක් චලනය කිරීමේදී යුගල ලෙස ප්‍රතිවිරුද්ධව ක්‍රියා කරන පේශි යුගලයකට උදාහරණය කුමක්ද?", "ද්විශීර්ෂ සහ ත්‍රිශීර්ෂ පේශි (අතේ)", "හෘත් පේශි සහ ප්‍රාචීරය", "ආමාශ පේශි සහ ශිරා", "මුහුණේ පේශි සහ අක්ෂි පේශි", "එක් පේශියක් සංකෝචනය වන විට ප්‍රතිවිරුද්ධ පේශිය ඉහිල් වේ (ප්‍රතිවිරුද්ධ ක්‍රියාව)."),
    q("පිට කොන්ද නොහොත් කශේරුව තුළින් ගමන් කරමින් මොළය හා දේහය සම්බන්ධ කරන ස්නායු රැහැන කුමක්ද?", "සුෂුම්නාව", "අන්නස්‍රෝතය", "මහා ධමනිය", "ශ්වාසනාලය", "කශේරුකාවල අස්ථි මගින් සුෂුම්නාවට ආරක්ෂාව සපයයි."),
    q("මිනිසාගේ ඒකාබද්ධ ප්‍රතිශක්තියේදී කිසියම් රෝගයකට එරෙහිව පූර්ව ආරක්ෂාව ලබා දීමට එන්නත් (Vaccines) ලබා දීමෙන් සිදු වන්නේ කුමක්ද?", "දුර්වල කළ රෝග කාරක මඟින් සක්‍රිය ප්‍රතිශක්තිය හා මතක සෛල ඇති කිරීම", "සියලු රුධිර සෛල විනාශ කිරීම", "ප්‍රතිදේහ විනාශ කිරීම", "උෂ්ණත්වය අඩු කිරීම", "එන්නත් මඟින් කෘත්‍රිම සක්‍රිය ප්‍රතිශක්තිය ලැබේ."),
    q("මිනිස් ඇසේ කිසිදු ආලෝක ප්‍රතිග්‍රාහක සෛලයක් නොමැති, දෘෂ්ටික ස්නායුව ඇසෙන් පිටවන ස්ථානය කුමක්ද?", "අන්ධ බින්දුව", "කහ ලපය", "කණිනිකාව", "තාරා මණ්ඩලය", "අන්ධ බින්දුව මත වැටෙන ප්‍රතිබිම්බ නොපෙනේ."),
    q("ඇසෙන් පිටත සිට ආලෝකය මුලින්ම වර්තනය කරමින් ඇස තුළට ඇතුළු වීමට ඉඩ දෙන විනිවිද පෙනෙන ඉදිරිපස ආවරණය කුමක්ද?", "ස්වච්ඡ මණ්ඩලය (Cornea)", "ශ්වේත පටලය", "දෘෂ්ටි විතානය", "රුධිරග්‍රාහී පටලය", "ඇසේ සිදුවන ආලෝක වර්තනයෙන් වැඩි ප්‍රමාණයක් ස්වච්ඡ මණ්ඩලයේදී වේ."),
    q("දකුණු කර්ණිකාවේ සිට දකුණු කෝෂිකාවට රුධිරය ගලා යන්නේ කුමන කපාටය හරහාද?", "ත්‍රිතුණ්ඩ කපාටය", "ද්විතුණ්ඩ කපාටය", "මහා ධමනි අඩසඳ කපාටය", "පුප්ඵුශීය අඩසඳ කපාටය", "ත්‍රිතුණ්ඩ කපාටය කපාට පෙති තුනකින් සමන්විත වේ."),
    q("මිනිසාගේ පෙනහැලි දෙක වටා ආරක්ෂාව සඳහා පිහිටි ද්විත්ව පටලමය ආවරණය හඳුන්වන්නේ කුමන නමින්ද?", "ප්ලූරාව (Pleural membranes)", "පෙරිකාඩියම", "පෙරිටෝනියම", "මෙනින්ජි පටල", "ප්ලූරා තරලය ආශ්වාස ප්‍රශ්වාසයේදී ඝර්ෂණය අඩු කරයි."),
    q("හෘදය වටා පිහිටි ආරක්ෂිත පටලමය කෝෂය හඳුන්වන්නේ කුමන නමින්ද?", "පෙරිකාඩියම (Pericardium)", "ප්ලූරාව", "ටෝනොප්ලාස්ටය", "මෙනින්ජිය", "පෙරිකාඩියල් තරලය හෘදය කම්පනවලින් හා ඝර්ෂණයෙන් රකී."),
    q("මිනිස් දේහයේ උපාංගීය සැකිල්ලට අයත් වන අස්ථියක් වන්නේ කුමක්ද?", "ප්‍රගණ්ඩාස්ථිය (Humerus)", "හිස්කබල", "උරෝස්ථිය", "කශේරුව", "අක්ෂීය සැකිල්ලට හිස්කබල, කශේරුව, උරෝස්ථිය හා පර්ශු අයත් වේ."),
    q("අත නැමීමේදී වැලමිට සන්ධිය ක්‍රියා කරන සන්ධි ආකාරය කුමක්ද?", "අසව් සන්ධිය (Hinge joint)", "ගෝල හා කුහර සන්ධිය", "අචල සන්ධිය", "කිවල් සන්ධිය", "වැලමිට හා දණහිස අසව් සන්ධි වන අතර උරහිස හා උකුළ ගෝල-කුහර සන්ධි වේ."),
    q("රුධිර නාල පද්ධතියේ ධමනි හා ශිරා එකිනෙක සම්බන්ධ කරමින් පටක සමඟ ද්‍රව්‍ය හුවමාරු කර ගන්නා සියුම් නාල මොනවාද?", "රුධිර කේශනාලිකා", "වසා නාල", "ස්නායු තන්තු", "පෙනේර නාල", "කේශනාලිකා බිත්තිය තනි සෛල ස්තරයකින් සෑදී ඇත."),
    q("මානව හෘද ශබ්දයේ 'ලබ්' (Lub) ශබ්දය ඇතිවීමට හේතුව කුමක්ද?", "ද්විතුණ්ඩ හා ත්‍රිතුණ්ඩ කපාට වැසීම", "අඩසඳ කපාට වැසීම", "කර්ණිකා සංකෝචනය", "මහා ධමනිය ප්‍රසාරණය වීම", "අඩසඳ කපාට වැසීමෙන් දෙවන හෘද ශබ්දය වන 'ඩබ්' ශබ්දය ඇතිවේ."),
    q("රුධිරයේ pH අගය සාමාන්‍යයෙන් පවතින සුළු භාෂ්මික පරාසය කුමක්ද?", "7.35–7.45", "5.0–5.5", "2.0–3.0", "9.5–10.5", "රුධිරයේ pH අගය පටු පරාසයක ඉතා තදින් නියාමනය වේ."),
    q("ක්ෂුද්‍රාන්ත්‍රයේදී මෝල්ටෝස් සීනි ග්ලූකෝස් බවට බිඳ දමන එන්සයිමය කුමක්ද?", "මෝල්ටේස්", "ලැක්ටේස්", "සුක්‍රේස්", "පෙප්සින්", "අන්ත්‍රික යුෂයේ ඇති මෝල්ටේස්, ලැක්ටේස් හා සුක්‍රේස් ඩයිසැකරයිඩ ජීර්ණය අවසන් කරයි."),
    q("ස්නායු පද්ධතියේ දේහ සෛලයේ සිට ආවේග පිටතට ගෙන යන දිගු තනි ප්‍රසරය කුමක්ද?", "ඇක්සනය (Axon)", "ඩෙන්ඩ්‍රෝනය", "උපාගමය", "සෛල දේහය", "බොහෝ ඇක්සන මයලින් කොපුවකින් ආවරණය වී ඇති බැවින් ආවේග වේගවත් වේ.")
  )
}
